CREATE OR REPLACE FUNCTION public.em_enrollment_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.em_principal() THEN RAISE EXCEPTION 'Admissions réservées au Super Admin Principal' USING ERRCODE='42501'; END IF; IF EXISTS(SELECT 1 FROM public.em_years WHERE id=NEW.year_id AND archive) THEN RAISE EXCEPTION 'Année archivée'; END IF; IF TG_OP='UPDATE' AND NEW.membre_id<>OLD.membre_id THEN RAISE EXCEPTION 'Fiche membre liée immuable'; END IF; IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM public.em_enrollments WHERE membre_id=NEW.membre_id) AND NOT EXISTS(SELECT 1 FROM public.membres WHERE id=NEW.membre_id AND categorie IN ('appeles','serviteurs_de_dieu')) THEN RAISE EXCEPTION 'Seuls les membres « Appelés » ou « Serviteurs de Dieu » peuvent être admis'; END IF; RETURN NEW; END $$;